\n  },\r\n  \"engines\": {\r\n    \"node\": \"\u003e=18.18.0\"\r\n  },\r\n  \"dependencies\": {\r\n    \"@azure/identity\": \"^4.7.0\",\r\n    \"@azure/logger\": \"^1.1.4\",\r\n    \"@azure/storage-blob\": \"^12.27.0\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@types/node\": \"^22.15.21\",\r\n    \"typescript\": \"^5.8.3\"\r\n  }\r\n}\r\n\n```\n\n### src\\blobStorageService.ts\n```\nimport { createReadStream } from \"node:fs\";\r\nimport { promises as fs } from \"node:fs\";\r\nimport { dirname } from \"node:path\";\r\nimport {\r\n  BlobServiceClient,\r\n  BlobItem,\r\n  BlockBlobParallelUploadOptions,\r\n  ContainerClient,\r\n  Tags\r\n} from \"@azure/storage-blob\";\r\n\r\nexport interface UploadBlobOptions {\r\n  metadata?: Record\u003cstring, string\u003e;\r\n  tags?: Tags;\r\n  blockSize?: number;\r\n  concurrency?: number;\r\n  leaseDurationSeconds?: number;\r\n}\r\n\r\nexport interface UploadBlobResult {\r\n  etag?: string;\r\n  lastModified?: Date;\r\n  usedLease: boolean;\r\n}\r\n\r\nexport class BlobStorageService {\r\n  constructor(private readonly blobServiceClient: BlobServiceClient) {}\r\n\r\n  async ensureContainer(containerName: string): Promise\u003cvoid\u003e {\r\n    await this.getContainerClient(containerName).createIfNotExists();\r\n  }\r\n\r\n  async uploadBlob(\r\n    containerName: string,\r\n    blobName: string,\r\n    filePath: string,\r\n    options: UploadBlobOptions = {}\r\n  ): Promise\u003cUploadBlobResult\u003e {\r\n    const containerClient = this.getContainerClient(containerName);\r\n    const blockBlobClient = containerClient.getBlockBlobClient(blobName);\r\n\r\n    const uploadOptions: BlockBlobParallelUploadOptions = {\r\n      metadata: options.metadata,\r\n      tags: options.tags\r\n    };\r\n\r\n    const streamOptions = {\r\n      bufferSize: options.blockSize ?? 8 * 1024 * 1024,\r\n      maxConcurrency: options.concurrency ?? 5\r\n    };\r\n\r\n    const blobExists = await blockBlobClient.exists();\r\n    let usedLease = false;\r\n\r\n    if (blobExists) {\r\n      const leaseClient = blockBlobClient.getBlobLeaseClient();\r\n      const leaseDurationSeconds = options.leaseDurationSeconds ?? 60;\r\n      const leaseResponse = await leaseClient.acquireLease(leaseDurationSeconds);\r\n\r\n      usedLease = true;\r\n      uploadOptions.conditions = { leaseId: leaseResponse.leaseId };\r\n\r\n      try {\r\n        const uploadResponse = await blockBlobClient.uploadStream(\r\n          createReadStream(filePath),\r\n          streamOptions.bufferSize,\r\n          streamOptions.maxConcurrency,\r\n          uploadOptions\r\n        );\r\n\r\n        return {\r\n          etag: uploadResponse.etag,\r\n          lastModified: uploadResponse.lastModified,\r\n          usedLease\r\n        };\r\n      } finally {\r\n        await leaseClient.releaseLease();\r\n      }\r\n    }\r\n\r\n    uploadOptions.conditions = { ifNoneMatch: \"*\" };\r\n\r\n    try {\r\n      const uploadResponse = await blockBlobClient.uploadStream(\r\n        createReadStream(filePath),\r\n        streamOptions.bufferSize,\r\n        streamOptions.maxConcurrency,\r\n        uploadOptions\r\n      );\r\n\r\n      return {\r\n        etag: uploadResponse.etag,\r\n        lastModified: uploadResponse.lastModified,\r\n        usedLease\r\n      };\r\n    } catch (error) {\r\n      if (!isBlobAlreadyExistsError(error)) {\r\n        throw error;\r\n      }\r\n\r\n      return this.uploadBlob(containerName, blobName, filePath, options);\r\n    }\r\n  }\r\n\r\n  async downloadBlob(containerName: string, blobName: string, destinationPath: string): Promise\u003cvoid\u003e {\r\n    await fs.mkdir(dirname(destinationPath), { recursive: true });\r\n\r\n    const blockBlobClient = this.getContainerClient(containerName).getBlockBlobClient(blobName);\r\n    await blockBlobClient.downloadToFile(destinationPath);\r\n  }\r\n\r\n  async listBlobs(containerName: string): Promise\u003cBlobItem[]\u003e {\r\n    const containerClient = this.getContainerClient(containerName);\r\n    const blobs: BlobItem[] = [];\r\n\r\n    for await (const blob of containerClient.listBlobsFlat({ includeMetadata: true, includeTags: true })) {\r\n      blobs.push(blob);\r\n    }\r\n\r\n    return blobs;\r\n  }\r\n\r\n  async deleteBlob(containerName: string, blobName: string): Promise\u003cvoid\u003e {\r\n    const blockBlobClient = this.getContainerClient(containerName).getBlockBlobClient(blobName);\r\n    await blockBlobClient.deleteIfExists({ deleteSnapshots: \"include\" });\r\n  }\r\n\r\n  private getContainerClient(containerName: string): ContainerClient {\r\n    return this.blobServiceClient.getContainerClient(containerName);\r\n  }\r\n}\r\n\r\nfunction isBlobAlreadyExistsError(error: unknown): boolean {\r\n  if (!error || typeof error !== \"object\") {\r\n    return false;\r\n  }\r\n\r\n  const statusCode = \"statusCode\" in error ? error.statusCode : undefined;\r\n  const details = \"details\" in error ? error.details : undefined;\r\n  const errorCode =\r\n    details \u0026\u0026 typeof details === \"object\" \u0026\u0026 details !== null \u0026\u0026 \"errorCode\" in details\r\n      ? details.errorCode\r\n      : undefined;\r\n\r\n  return statusCode === 412 || errorCode === \"ConditionNotMet\";\r\n}\r\n\n```\n\n### src\\config.ts\n```\nimport { DefaultAzureCredential } from \"@azure/identity\";\r\nimport { AzureLogger, AzureLogLevel, setLogLevel } from \"@azure/logger\";\r\nimport {\r\n  BlobServiceClient,\r\n  StorageRetryPolicyType,\r\n  StoragePipelineOptions\r\n} from \"@azure/storage-blob\";\r\n\r\nconst SUPPORTED_LOG_LEVELS: AzureLogLevel[] = [\"verbose\", \"info\", \"warning\", \"error\"];\r\n\r\nexport interface BlobStorageConfig {\r\n  endpoint: string;\r\n  containerName: string;\r\n  retryMaxTries: number;\r\n  retryDelayInMs: number;\r\n  retryMaxDelayInMs: number;\r\n  sdkLogLevel: AzureLogLevel;\r\n}\r\n\r\nexport function loadBlobStorageConfig(): BlobStorageConfig {\r\n  const endpoint = process.env.AZURE_STORAGE_BLOB_ENDPOINT;\r\n\r\n  if (!endpoint) {\r\n    throw new Error(\"AZURE_STORAGE_BLOB_ENDPOINT must be set to the Blob service endpoint.\");\r\n  }\r\n\r\n  const sdkLogLevel = parseLogLevel(process.env.AZURE_SDK_LOG_LEVEL);\r\n\r\n  return {\r\n    endpoint,\r\n    containerName: process.env.AZURE_STORAGE_CONTAINER_NAME ?? \"blob-demo\",\r\n    retryMaxTries: parsePositiveInteger(process.env.AZURE_STORAGE_RETRY_MAX_TRIES, 5),\r\n    retryDelayInMs: parsePositiveInteger(process.env.AZURE_STORAGE_RETRY_DELAY_MS, 800),\r\n    retryMaxDelayInMs: parsePositiveInteger(process.env.AZURE_STORAGE_RETRY_MAX_DELAY_MS, 8_000),\r\n    sdkLogLevel\r\n  };\r\n}\r\n\r\nexport function createBlobServiceClient(config: BlobStorageConfig): BlobServiceClient {\r\n  setLogLevel(config.sdkLogLevel);\r\n  AzureLogger.log = (...args: unknown[]) =\u003e {\r\n    console.log(\"[azure-sdk]\", ...args);\r\n  };\r\n\r\n  const credential = new DefaultAzureCredential();\r\n\r\n  const options: StoragePipelineOptions = {\r\n    retryOptions: {\r\n      maxTries: config.retryMaxTries,\r\n      retryDelayInMs: config.retryDelayInMs,\r\n      maxRetryDelayInMs: config.retryMaxDelayInMs,\r\n      retryPolicyType: StorageRetryPolicyType.EXPONENTIAL\r\n    }\r\n  };\r\n\r\n  return new BlobServiceClient(config.endpoint, credential, options);\r\n}\r\n\r\nfunction parsePositiveInteger(value: string | undefined, fallback: number): number {\r\n  if (!value) {\r\n    return fallback;\r\n  }\r\n\r\n  const parsed = Number.parseInt(value, 10);\r\n\r\n  if (!Number.isInteger(parsed) || parsed \u003c= 0) {\r\n    throw new Error(`Expected a positive integer but received \"${value}\".`);\r\n  }\r\n\r\n  return parsed;\r\n}\r\n\r\nfunction parseLogLevel(value: string | undefined): AzureLogLevel {\r\n  if (!value) {\r\n    return \"info\";\r\n  }\r\n\r\n  if (SUPPORTED_LOG_LEVELS.includes(value as AzureLogLevel)) {\r\n    return value as AzureLogLevel;\r\n  }\r\n\r\n  throw new Error(\r\n    `Unsupported AZURE_SDK_LOG_LEVEL \"${value}\". Supported values: ${SUPPORTED_LOG_LEVELS.join(\", \")}.`\r\n  );\r\n}\r\n\n```\n\n### src\\index.ts\n```\nimport { promises as fs } from \"node:fs\";\r\nimport { join } from \"node:path\";\r\nimport { Tags } from \"@azure/storage-blob\";\r\nimport { BlobStorageService } from \"./blobStorageService\";\r\nimport { createBlobServiceClient, loadBlobStorageConfig } from \"./config\";\r\n\r\nasync function main(): Promise\u003cvoid\u003e {\r\n  const config = loadBlobStorageConfig();\r\n  const blobServiceClient = createBlobServiceClient(config);\r\n  const blobStorageService = new BlobStorageService(blobServiceClient);\r\n\r\n  const workingDirectory = join(process.cwd(), \"demo-artifacts\");\r\n  const uploadFilePath = join(workingDirectory, \"sample-upload.txt\");\r\n  const downloadFilePath = join(workingDirectory, \"downloaded-sample.txt\");\r\n  const blobName = \"sample-upload.txt\";\r\n  const initialTags: Tags = {\r\n    project: \"azure-blob-manager\",\r\n    scenario: \"demo\",\r\n    stage: \"initial\"\r\n  };\r\n  const updatedTags: Tags = {\r\n    project: \"azure-blob-manager\",\r\n    scenario: \"demo\",\r\n    stage: \"updated\"\r\n  };\r\n\r\n  await fs.mkdir(workingDirectory, { recursive: true });\r\n\r\n  console.log(`Using container \"${config.containerName}\" at ${config.endpoint}`);\r\n  console.log(\"Ensuring container exists...\");\r\n  await blobStorageService.ensureContainer(config.containerName);\r\n\r\n  console.log(\"Preparing sample file...\");\r\n  await fs.writeFile(uploadFilePath, \"Initial blob content written from the TypeScript demo.\\n\", \"utf8\");\r\n\r\n  console.log(\"Uploading sample blob with index tags...\");\r\n  const uploadResult = await blobStorageService.uploadBlob(config.containerName, blobName, uploadFilePath, {\r\n    metadata: {\r\n      source: \"demo-script\",\r\n      stage: \"initial\"\r\n    },\r\n    tags: initialTags\r\n  });\r\n  console.log(`Upload complete. Lease used: ${uploadResult.usedLease}`);\r\n\r\n  console.log(\"Listing blobs in container...\");\r\n  const blobs = await blobStorageService.listBlobs(config.containerName);\r\n  for (const blob of blobs) {\r\n    const tags = blob.tags ? JSON.stringify(blob.tags) : \"{}\";\r\n    console.log(`- ${blob.name} | tags=${tags}`);\r\n  }\r\n\r\n  console.log(\"Downloading blob...\");\r\n  await blobStorageService.downloadBlob(config.containerName, blobName, downloadFilePath);\r\n  const downloadedContent = await fs.readFile(downloadFilePath, \"utf8\");\r\n  console.log(\"Downloaded content:\");\r\n  console.log(downloadedContent.trimEnd());\r\n\r\n  console.log(\"Overwriting blob while holding a lease...\");\r\n  await fs.writeFile(uploadFilePath, \"Updated blob content written after lease acquisition.\\n\", \"utf8\");\r\n  const overwriteResult = await blobStorageService.uploadBlob(config.containerName, blobName, uploadFilePath, {\r\n    metadata: {\r\n      source: \"demo-script\",\r\n      stage: \"updated\"\r\n    },\r\n    tags: updatedTags\r\n  });\r\n  console.log(`Overwrite complete. Lease used: ${overwriteResult.usedLease}`);\r\n\r\n  console.log(\"Deleting blob...\");\r\n  await blobStorageService.deleteBlob(config.containerName, blobName);\r\n  console.log(\"Blob deleted.\");\r\n}\r\n\r\nmain().catch((error: unknown) =\u003e {\r\n  console.error(\"Blob demo failed.\");\r\n\r\n  if (error instanceof Error) {\r\n    console.error(error.message);\r\n    if (error.stack) {\r\n      console.error(error.stack);\r\n    }\r\n  } else {\r\n    console.error(error);\r\n  }\r\n\r\n  process.exitCode = 1;\r\n});\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2022\",\r\n    \"module\": \"CommonJS\",\r\n    \"moduleResolution\": \"Node\",\r\n    \"rootDir\": \"src\",\r\n    \"outDir\": \"dist\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"skipLibCheck\": true,\r\n    \"